INDEX = '<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Prism Panel</title>\n<link href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css" rel="stylesheet">\n<style>\n:root{--bg:#f8fafc;--card:#fff;--border:#e2e8f0;--primary:#4f46e5;--primary-h:#4338ca;--text:#0f172a;--muted:#64748b;--success:#059669;--radius:16px;--shadow:0 4px 24px rgba(15,23,42,.06)}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\'Vazirmatn\',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;display:flex;align-items:center;justify-content:center;background-image:radial-gradient(ellipse at 70% 20%,rgba(79,70,229,.08),transparent 50%),radial-gradient(ellipse at 20% 80%,rgba(5,150,105,.06),transparent 40%)}\n.wrap{max-width:440px;width:92%;text-align:center}\n.logo{width:64px;height:64px;margin:0 auto 1rem;background:linear-gradient(135deg,#4f46e5,#7c3aed);border-radius:18px;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 24px rgba(79,70,229,.25)}\n.logo svg{width:32px;height:32px;fill:#fff}\nh1{font-size:1.75rem;font-weight:700;margin-bottom:.4rem}\np{color:var(--muted);line-height:1.7;margin-bottom:1.75rem;font-size:.95rem}\n.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:2rem;box-shadow:var(--shadow)}\n.badge{display:inline-flex;align-items:center;gap:.4rem;background:#ecfdf5;color:var(--success);padding:.35rem .9rem;border-radius:999px;font-size:.82rem;font-weight:500;margin-bottom:1.25rem}\n.badge svg{width:14px;height:14px}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;width:100%;padding:.95rem;background:var(--primary);color:#fff;border:none;border-radius:12px;font-family:inherit;font-weight:600;font-size:1rem;cursor:pointer;text-decoration:none;transition:.15s}\n.btn:hover{background:var(--primary-h);transform:translateY(-1px)}\n.btn svg{width:18px;height:18px;fill:currentColor}\n.domain{font-size:.85rem;color:var(--muted);margin-top:1.25rem}\n.domain code{background:#f1f5f9;padding:.15rem .45rem;border-radius:6px;color:#4f46e5;font-size:.8rem}\n.foot{margin-top:1.75rem;font-size:.78rem;color:var(--muted)}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <div class="logo"><svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg></div>\n  <h1>Prism Panel</h1>\n  <p>پنل حرفه\u200cای مدیریت پروکسی<br>VLESS + Trojan · چند کاربره · آماده Railway</p>\n  <div class="card">\n    <div class="badge"><svg viewBox="0 0 24 24" fill="currentColor"><circle cx="12" cy="12" r="6"/></svg> سرویس آنلاین است</div>\n    <a href="/login" class="btn"><svg viewBox="0 0 24 24"><path d="M10 17l5-5-5-5v10z"/></svg> ورود به پنل مدیریت</a>\n    <p class="domain">دامنه: <code>{{ domain }}</code></p>\n  </div>\n  <p class="foot">Prism Panel v2 · Built for Railway</p>\n</div>\n</body>\n</html>'

LOGIN = '<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>ورود | Prism Panel</title>\n<link href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css" rel="stylesheet">\n<style>\n:root{--bg:#f8fafc;--card:#fff;--border:#e2e8f0;--primary:#4f46e5;--primary-h:#4338ca;--text:#0f172a;--muted:#64748b;--danger:#dc2626;--radius:16px;--shadow:0 4px 24px rgba(15,23,42,.06)}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\'Vazirmatn\',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;display:flex;align-items:center;justify-content:center;background-image:radial-gradient(ellipse at 50% 0%,rgba(79,70,229,.07),transparent 55%)}\n.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:2.25rem;width:92%;max-width:400px;box-shadow:var(--shadow)}\n.logo{width:48px;height:48px;margin:0 auto 1rem;background:linear-gradient(135deg,#4f46e5,#7c3aed);border-radius:14px;display:flex;align-items:center;justify-content:center}\n.logo svg{width:24px;height:24px;fill:#fff}\nh1{text-align:center;font-size:1.35rem;margin-bottom:.3rem}\n.sub{text-align:center;color:var(--muted);font-size:.9rem;margin-bottom:1.75rem}\nlabel{display:block;font-size:.85rem;color:var(--muted);margin-bottom:.4rem}\ninput{width:100%;padding:.85rem 1rem;border:1px solid var(--border);border-radius:12px;font-family:inherit;font-size:1rem;background:#f8fafc;color:var(--text);outline:none;margin-bottom:1.25rem;transition:.15s}\ninput:focus{border-color:var(--primary);background:#fff;box-shadow:0 0 0 3px rgba(79,70,229,.12)}\nbutton{width:100%;padding:.9rem;background:var(--primary);color:#fff;border:none;border-radius:12px;font-family:inherit;font-weight:600;font-size:1rem;cursor:pointer;transition:.15s}\nbutton:hover{background:var(--primary-h)}\n.err{background:#fef2f2;color:var(--danger);padding:.7rem;border-radius:10px;font-size:.88rem;text-align:center;margin-bottom:1rem;display:none}\n.back{display:block;text-align:center;margin-top:1.25rem;color:var(--muted);font-size:.85rem;text-decoration:none}\n.back:hover{color:var(--primary)}\n</style>\n</head>\n<body>\n<div class="card">\n  <div class="logo"><svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg></div>\n  <h1>ورود به پنل</h1>\n  <p class="sub">رمز عبور ادمین را وارد کنید</p>\n  <div class="err" id="err"></div>\n  <form id="f">\n    <label>رمز عبور</label>\n    <input type="password" id="pw" required autofocus placeholder="••••••••">\n    <button type="submit">ورود</button>\n  </form>\n  <a href="/" class="back">← بازگشت</a>\n</div>\n<script>\ndocument.getElementById(\'f\').onsubmit=async e=>{\n  e.preventDefault();\n  const err=document.getElementById(\'err\');\n  err.style.display=\'none\';\n  try{\n    const r=await fetch(\'/api/login\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({password:document.getElementById(\'pw\').value})});\n    if(r.ok) location.href=\'/dashboard\';\n    else{err.textContent=\'رمز عبور اشتباه است\';err.style.display=\'block\'}\n  }catch{err.textContent=\'خطا در ارتباط\';err.style.display=\'block\'}\n};\n</script>\n</body>\n</html>'

DASHBOARD = '<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>داشبورد | Prism Panel</title>\n<link href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css" rel="stylesheet">\n<style>\n:root{--bg:#f1f5f9;--card:#fff;--border:#e2e8f0;--primary:#4f46e5;--primary-h:#4338ca;--text:#0f172a;--muted:#64748b;--success:#059669;--danger:#dc2626;--warn:#d97706;--radius:14px;--shadow:0 1px 3px rgba(15,23,42,.06)}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\'Vazirmatn\',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh}\nheader{background:var(--card);border-bottom:1px solid var(--border);padding:.85rem 1.5rem;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:40}\n.brand{display:flex;align-items:center;gap:.6rem;font-weight:700;font-size:1.1rem}\n.brand .ico{width:32px;height:32px;background:linear-gradient(135deg,#4f46e5,#7c3aed);border-radius:9px;display:flex;align-items:center;justify-content:center}\n.brand .ico svg{width:16px;height:16px;fill:#fff}\nnav{display:flex;align-items:center;gap:1rem}\n.domain{font-size:.8rem;color:var(--muted);background:#f1f5f9;padding:.3rem .7rem;border-radius:8px}\n.btn{display:inline-flex;align-items:center;gap:.35rem;padding:.5rem 1rem;border-radius:10px;border:none;font-family:inherit;font-weight:500;font-size:.88rem;cursor:pointer;transition:.15s;text-decoration:none}\n.btn svg{width:16px;height:16px;fill:currentColor}\n.btn-p{background:var(--primary);color:#fff}.btn-p:hover{background:var(--primary-h)}\n.btn-o{background:#fff;border:1px solid var(--border);color:var(--text)}.btn-o:hover{border-color:#cbd5e1}\n.btn-d{background:#fef2f2;color:var(--danger)}.btn-d:hover{background:#fee2e2}\n.btn-sm{padding:.35rem .7rem;font-size:.8rem}\nmain{max-width:1100px;margin:0 auto;padding:1.5rem}\n.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:1rem;margin-bottom:1.75rem}\n.stat{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:1.15rem;box-shadow:var(--shadow)}\n.stat .l{font-size:.8rem;color:var(--muted);margin-bottom:.3rem}\n.stat .v{font-size:1.45rem;font-weight:700}\n.sec{display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem}\n.sec h2{font-size:1.15rem}\n.table-wrap{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow)}\ntable{width:100%;border-collapse:collapse}\nth,td{padding:.85rem 1rem;text-align:right;border-bottom:1px solid var(--border);font-size:.9rem}\nth{background:#f8fafc;color:var(--muted);font-weight:500;font-size:.8rem}\ntr:last-child td{border-bottom:none}\ntr:hover td{background:#fafbfc}\n.badge{display:inline-block;padding:.18rem .55rem;border-radius:999px;font-size:.72rem;font-weight:500}\n.b-g{background:#ecfdf5;color:var(--success)}.b-r{background:#fef2f2;color:var(--danger)}.b-b{background:#eef2ff;color:#4f46e5}.b-y{background:#fffbeb;color:var(--warn)}\n.acts{display:flex;gap:.35rem;flex-wrap:wrap}\n.empty{text-align:center;padding:3rem;color:var(--muted)}\n.modal-bg{position:fixed;inset:0;background:rgba(15,23,42,.4);display:none;align-items:center;justify-content:center;z-index:100;padding:1rem;backdrop-filter:blur(4px)}\n.modal-bg.on{display:flex}\n.modal{background:#fff;border-radius:18px;padding:1.75rem;width:100%;max-width:440px;max-height:90vh;overflow-y:auto;box-shadow:0 20px 50px rgba(15,23,42,.15)}\n.modal h3{font-size:1.15rem;margin-bottom:1.25rem}\n.fg{margin-bottom:1rem}\n.fg label{display:block;font-size:.82rem;color:var(--muted);margin-bottom:.35rem}\n.fg input,.fg select{width:100%;padding:.7rem .9rem;border:1px solid var(--border);border-radius:10px;font-family:inherit;font-size:.95rem;background:#f8fafc;outline:none}\n.fg input:focus,.fg select:focus{border-color:var(--primary);background:#fff}\n.ma{display:flex;gap:.6rem;margin-top:1.25rem}\n.ma button{flex:1}\n.info{margin-top:1.75rem;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:1.25rem;font-size:.88rem;color:var(--muted);line-height:1.85;box-shadow:var(--shadow)}\n.info strong{color:var(--text)}\n.info code{background:#f1f5f9;padding:.1rem .4rem;border-radius:5px;color:#4f46e5;font-size:.8rem}\n@media(max-width:720px){.table-wrap{overflow-x:auto}table{min-width:720px}header{flex-direction:column;gap:.6rem}}\n\n\n\n\n.icon-btn{display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:9px;border:1px solid #e2e8f0;background:#fff;cursor:pointer;padding:0;transition:.15s}\n.icon-btn:hover{background:#f8fafc;border-color:#cbd5e1}\n.icon-btn:hover svg{stroke:#64748b}\n.icon-btn svg{display:block;pointer-events:none}\n.settings-bg{position:fixed;inset:0;background:rgba(15,23,42,.4);display:none;align-items:center;justify-content:center;z-index:120;padding:1rem;backdrop-filter:blur(3px)}\n.settings-bg.on{display:flex}\n.settings-modal{background:#fff;border-radius:16px;width:100%;max-width:380px;padding:1.4rem 1.5rem 1.5rem;box-shadow:0 20px 50px rgba(15,23,42,.18);border:1px solid #e2e8f0}\n.settings-modal h3{font-size:1rem;margin-bottom:1.1rem;display:flex;align-items:center;justify-content:space-between;color:#0f172a}\n.settings-modal .close{background:none;border:none;font-size:1.35rem;cursor:pointer;color:#94a3b8;line-height:1;padding:0 4px}\n.settings-modal .close:hover{color:#64748b}\n.settings-modal .fg{margin-bottom:.85rem}\n.settings-modal label{display:block;font-size:.8rem;color:#64748b;margin-bottom:.3rem}\n.settings-modal input{width:100%;padding:.7rem .85rem;border:1px solid #e2e8f0;border-radius:10px;font-family:inherit;font-size:.92rem;background:#f8fafc;outline:none}\n.settings-modal input:focus{border-color:#4f46e5;background:#fff}\n.settings-msg{font-size:.82rem;margin-top:.55rem;display:none;padding:.5rem .65rem;border-radius:8px}\n.settings-msg.ok{display:block;background:#ecfdf5;color:#059669}\n.settings-msg.err{display:block;background:#fef2f2;color:#dc2626}\n\n</style>\n</head>\n<body>\n<header>\n  <div class="brand"><div class="ico"><svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg></div> Prism Panel</div>\n  <nav>\n    <span class="domain">{{ domain }}</span>\n    <button type="button" class="icon-btn" onclick="openSettings()" title="تنظیمات" aria-label="تنظیمات">\n      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">\n        <circle cx="12" cy="12" r="3"/>\n        <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>\n      </svg>\n    </button>\n    <button class="btn btn-o btn-sm" onclick="logout()">خروج</button>\n  </nav>\n</header>\n<main>\n  <div class="stats">\n    <div class="stat"><div class="l">کاربران</div><div class="v">{{ users|length }}</div></div>\n    <div class="stat"><div class="l">اتصالات فعال</div><div class="v">{{ active }}</div></div>\n    <div class="stat"><div class="l">ترافیک کل</div><div class="v">{{ total_traffic }}</div></div>\n    <div class="stat"><div class="l">وضعیت</div><div class="v" style="color:var(--success);font-size:1.1rem">آنلاین</div></div>\n  </div>\n  <div class="sec">\n    <h2>مدیریت کاربران</h2>\n    <button class="btn btn-p" onclick="openM()"><svg viewBox="0 0 24 24"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg> کاربر جدید</button>\n  </div>\n  <div class="table-wrap">\n    {% if users %}\n    <table>\n      <thead><tr><th>نام</th><th>پروتکل</th><th>وضعیت</th><th>مصرف / سقف</th><th>انقضا</th><th>عملیات</th></tr></thead>\n      <tbody>\n        {% for u in users %}\n        <tr>\n          <td><strong>{{ u.name }}</strong>{% if u.note %}<br><small style="color:var(--muted)">{{ u.note }}</small>{% endif %}<br><small style="color:#94a3b8;font-size:.72rem">{{ u.uuid[:8] }}…</small></td>\n          <td><span class="badge b-b">{{ u.protocol|upper }}</span></td>\n          <td>{% if u.enabled %}<span class="badge b-g">فعال</span>{% else %}<span class="badge b-r">غیرفعال</span>{% endif %}</td>\n          <td>{{ u._used }} / {{ u._limit }}</td>\n          <td>{% if u._expire %}<small>{{ u._expire }}</small>{% else %}<span class="badge b-y">نامحدود</span>{% endif %}</td>\n          <td>\n            <div class="acts">\n              {% if u.vless %}<button class="btn btn-o btn-sm" onclick="cp(\'{{ u.vless }}\')">VLESS</button>{% endif %}\n              {% if u.trojan %}<button class="btn btn-o btn-sm" onclick="cp(\'{{ u.trojan }}\')">Trojan</button>{% endif %}\n              <button class="btn btn-o btn-sm" onclick="cp(\'{{ url }}/sub/{{ u.uuid }}\')">ساب</button>\n              <button class="btn btn-o btn-sm" onclick="pingTest(\'{{ u.uuid }}\', this)">تست</button>\n              <a class="btn btn-o btn-sm" href="/u/{{ u.uuid }}" target="_blank">صفحه کاربر</a>\n              <button class="btn btn-d btn-sm" onclick="del(\'{{ u.uuid }}\')">حذف</button>\n            </div>\n          </td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n    {% else %}\n    <div class="empty">هنوز کاربری ندارید. اولین کاربر را بسازید.</div>\n    {% endif %}\n  </div>\n  <div class="info">\n    <strong>اطلاعات فنی</strong><br>\n    پروتکل\u200cها: VLESS-WS-TLS و Trojan-WS-TLS · پورت ۴۴۳<br>\n    مسیر VLESS: <code>{{ vless_path }}</code> · مسیر Trojan: <code>{{ trojan_path }}</code><br>\n    کلاینت\u200cها: Hiddify · v2rayNG · NekoBox · Streisand · v2rayN<br>\n    صفحه وضعیت کاربر: <code>{{ url }}/u/{uuid}</code>\n  </div>\n</main>\n<div class="modal-bg" id="m">\n  <div class="modal">\n    <h3>ایجاد کاربر جدید</h3>\n    <form id="cf">\n      <div class="fg"><label>نام کاربر</label><input name="name" required placeholder="مثلاً: موبایل من"></div>\n      <div class="fg"><label>پروتکل</label>\n        <select name="protocol">\n          <option value="vless" selected>VLESS (پیشنهادی)</option>\n          <option value="trojan">Trojan</option>\n          <option value="both">هر دو (VLESS + Trojan)</option>\n        </select>\n      </div>\n      <div class="fg"><label>پروفایل امنیتی (Fingerprint)</label>\n        <select name="fingerprint">\n          <option value="chrome" selected>chrome</option>\n          <option value="firefox">firefox</option>\n          <option value="safari">safari</option>\n          <option value="ios">ios</option>\n          <option value="android">android</option>\n          <option value="edge">edge</option>\n          <option value="random">random</option>\n          <option value="randomized">randomized</option>\n        </select>\n      </div>\n      <div class="fg"><label>ALPN</label>\n        <select name="alpn">\n          <option value="http/1.1" selected>http/1.1 (بهترین برای Railway)</option>\n          <option value="h2,http/1.1">h2,http/1.1</option>\n          <option value="h2">h2</option>\n        </select>\n      </div>\n      <div class="fg"><label>حجم ترافیک (گیگابایت) — ۰ = نامحدود</label><input type="number" name="traffic_gb" value="0" min="0" step="0.5"></div>\n      <div class="fg"><label>مدت اعتبار (روز) — ۰ = نامحدود</label><input type="number" name="expire_days" value="0" min="0"></div>\n      <div class="fg"><label>حداکثر اتصال همزمان — ۰ = نامحدود</label><input type="number" name="max_conn" value="0" min="0"></div>\n      <div class="fg"><label>یادداشت (اختیاری)</label><input name="note" placeholder="توضیح کوتاه"></div>\n      <div class="ma">\n        <button type="button" class="btn btn-o" onclick="closeM()">انصراف</button>\n        <button type="submit" class="btn btn-p">ایجاد کاربر</button>\n      </div>\n    </form>\n  </div>\n</div>\n<script>\nfunction openM(){document.getElementById(\'m\').classList.add(\'on\')}\nfunction closeM(){document.getElementById(\'m\').classList.remove(\'on\')}\ndocument.getElementById(\'m\').onclick=e=>{if(e.target.id===\'m\')closeM()};\ndocument.getElementById(\'cf\').onsubmit=async e=>{\n  e.preventDefault();\n  const f=e.target;\n  const body={name:f.name.value,protocol:f.protocol.value,fingerprint:f.fingerprint.value,alpn:f.alpn.value,traffic_gb:parseFloat(f.traffic_gb.value)||0,expire_days:parseInt(f.expire_days.value)||0,max_conn:parseInt(f.max_conn.value)||0,note:f.note.value||\'\',enabled:true};\n  const r=await fetch(\'/api/users\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(body)});\n  if(r.ok) location.reload(); else alert(\'خطا در ایجاد\');\n};\nasync function pingTest(uid, btn){\n  const old=btn.textContent;\n  btn.textContent=\'...\';\n  btn.disabled=true;\n  try{\n    const r=await fetch(\'/api/ping-test/\'+uid);\n    const j=await r.json();\n    if(j.ok) alert(\'اتصال به سرور OK\\nLatency: \'+j.latency_ms+\' ms\\nPath: \'+j.path_vless+\'\\nوضعیت کاربر: \'+(j.user_enabled?\'فعال\':\'غیرفعال\'));\n    else alert(\'خطا: \'+(j.error||\'timeout\')+\'\\nHost: \'+j.host);\n  }catch(e){alert(\'خطا در تست\');}\n  btn.textContent=old;\n  btn.disabled=false;\n}\nasync function del(uid){if(!confirm(\'حذف این کاربر؟\'))return;await fetch(\'/api/users/\'+uid,{method:\'DELETE\'});location.reload()}\nfunction cp(t){if(!t)return;navigator.clipboard.writeText(t).then(()=>alert(\'کپی شد!\'))}\n\nfunction openSettings(){\n  var el=document.getElementById(\'settingsBg\');\n  if(el) el.classList.add(\'on\');\n}\nfunction closeSettings(){\n  var el=document.getElementById(\'settingsBg\');\n  if(el) el.classList.remove(\'on\');\n  var msg=document.getElementById(\'pwdMsg\');\n  if(msg){msg.className=\'settings-msg\';msg.textContent=\'\';}\n}\ndocument.addEventListener(\'click\',function(e){\n  if(e.target && e.target.id===\'settingsBg\') closeSettings();\n});\nvar pwdForm=document.getElementById(\'pwdForm\');\nif(pwdForm){\n  pwdForm.onsubmit=async function(e){\n    e.preventDefault();\n    var f=e.target;\n    var msg=document.getElementById(\'pwdMsg\');\n    msg.className=\'settings-msg\';\n    if(f.new_password.value!==f.confirm.value){msg.textContent=\'رمز جدید و تکرار آن یکسان نیست\';msg.className=\'settings-msg err\';return;}\n    if(f.new_password.value.length<4){msg.textContent=\'رمز باید حداقل ۴ کاراکتر باشد\';msg.className=\'settings-msg err\';return;}\n    try{\n      var r=await fetch(\'/api/change-password\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({current:f.current.value,new_password:f.new_password.value})});\n      var j=await r.json().catch(function(){return {};});\n      if(r.ok){msg.textContent=\'رمز با موفقیت تغییر کرد\';msg.className=\'settings-msg ok\';f.reset();}\n      else{msg.textContent=j.detail||\'خطا در تغییر رمز\';msg.className=\'settings-msg err\';}\n    }catch(err){msg.textContent=\'خطا در ارتباط با سرور\';msg.className=\'settings-msg err\';}\n  };\n}\n\nasync function logout(){await fetch(\'/api/logout\',{method:\'POST\'});location.href=\'/login\'}\n</script>\n\n\n<div class="settings-bg" id="settingsBg">\n  <div class="settings-modal" role="dialog" aria-modal="true">\n    <h3>\n      <span>تنظیمات</span>\n      <button type="button" class="close" onclick="closeSettings()" aria-label="بستن">×</button>\n    </h3>\n    <form id="pwdForm">\n      <div class="fg">\n        <label>رمز فعلی</label>\n        <input type="password" name="current" required placeholder="رمز فعلی" autocomplete="current-password">\n      </div>\n      <div class="fg">\n        <label>رمز جدید</label>\n        <input type="password" name="new_password" required minlength="4" placeholder="حداقل ۴ کاراکتر" autocomplete="new-password">\n      </div>\n      <div class="fg">\n        <label>تکرار رمز جدید</label>\n        <input type="password" name="confirm" required minlength="4" placeholder="تکرار رمز جدید" autocomplete="new-password">\n      </div>\n      <button type="submit" class="btn btn-p" style="width:100%;justify-content:center;margin-top:.25rem">ذخیره رمز جدید</button>\n      <div class="settings-msg" id="pwdMsg"></div>\n    </form>\n  </div>\n</div>\n\n</body>\n</html>'

PORTAL = '<!DOCTYPE html>\n<html lang="fa" dir="rtl">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>{{ user.name }} | Prism</title>\n<link href="https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css" rel="stylesheet">\n<style>\n:root{--bg:#f8fafc;--card:#fff;--border:#e2e8f0;--primary:#4f46e5;--text:#0f172a;--muted:#64748b;--success:#059669;--danger:#dc2626;--radius:16px;--shadow:0 4px 20px rgba(15,23,42,.06)}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\'Vazirmatn\',system-ui,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;padding:1.5rem}\n.wrap{max-width:480px;margin:0 auto}\n.header{text-align:center;margin-bottom:1.5rem}\n.avatar{width:56px;height:56px;background:linear-gradient(135deg,#4f46e5,#7c3aed);border-radius:16px;display:flex;align-items:center;justify-content:center;margin:0 auto .75rem;box-shadow:0 6px 18px rgba(79,70,229,.25)}\n.avatar svg{width:28px;height:28px;fill:#fff}\nh1{font-size:1.35rem;margin-bottom:.25rem}\n.status{display:inline-flex;align-items:center;gap:.35rem;padding:.3rem .8rem;border-radius:999px;font-size:.8rem;font-weight:500;margin-top:.4rem}\n.s-ok{background:#ecfdf5;color:var(--success)}.s-no{background:#fef2f2;color:var(--danger)}\n.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:1.35rem;margin-bottom:1rem;box-shadow:var(--shadow)}\n.card h3{font-size:.95rem;margin-bottom:1rem;display:flex;align-items:center;gap:.4rem}\n.card h3 svg{width:18px;height:18px;fill:var(--primary)}\n.row{display:flex;justify-content:space-between;padding:.55rem 0;border-bottom:1px solid #f1f5f9;font-size:.9rem}\n.row:last-child{border-bottom:none}\n.row .k{color:var(--muted)}.row .v{font-weight:500}\n.bar{height:8px;background:#e2e8f0;border-radius:99px;overflow:hidden;margin-top:.6rem}\n.bar i{display:block;height:100%;background:linear-gradient(90deg,#4f46e5,#7c3aed);border-radius:99px}\n.btns{display:flex;flex-direction:column;gap:.6rem}\n.btn{display:flex;align-items:center;justify-content:center;gap:.5rem;padding:.85rem;border-radius:12px;border:none;font-family:inherit;font-weight:600;font-size:.92rem;cursor:pointer;text-decoration:none;transition:.15s}\n.btn svg{width:18px;height:18px;fill:currentColor}\n.btn-p{background:var(--primary);color:#fff}.btn-p:hover{opacity:.92}\n.btn-o{background:#f1f5f9;color:var(--text);border:1px solid var(--border)}.btn-o:hover{background:#e2e8f0}\n.linkbox{background:#f8fafc;border:1px solid var(--border);border-radius:10px;padding:.7rem .9rem;font-family:monospace;font-size:.72rem;word-break:break-all;direction:ltr;text-align:left;margin-top:.6rem;color:#334155}\n.qr{text-align:center;margin-top:.75rem}\n.qr img{width:160px;height:160px;border-radius:12px;border:1px solid var(--border)}\n.foot{text-align:center;margin-top:1.5rem;font-size:.75rem;color:var(--muted)}\n</style>\n</head>\n<body>\n<div class="wrap">\n  <div class="header">\n    <div class="avatar"><svg viewBox="0 0 24 24"><path d="M12 12c2.7 0 4.8-2.1 4.8-4.8S14.7 2.4 12 2.4 7.2 4.5 7.2 7.2 9.3 12 12 12zm0 2.4c-3.2 0-9.6 1.6-9.6 4.8v2.4h19.2v-2.4c0-3.2-6.4-4.8-9.6-4.8z"/></svg></div>\n    <h1>{{ user.name }}</h1>\n    {% if valid %}<div class="status s-ok">فعال و قابل استفاده</div>{% else %}<div class="status s-no">غیرفعال یا منقضی</div>{% endif %}\n  </div>\n  <div class="card">\n    <h3><svg viewBox="0 0 24 24"><path d="M3 13h2v-2H3v2zm0 4h2v-2H3v2zm0-8h2V7H3v2zm4 4h14v-2H7v2zm0 4h14v-2H7v2zM7 7v2h14V7H7z"/></svg> وضعیت اشتراک</h3>\n    <div class="row"><span class="k">مصرف شده</span><span class="v">{{ used_str }}</span></div>\n    <div class="row"><span class="k">سقف ترافیک</span><span class="v">{{ limit_str }}</span></div>\n    <div class="row"><span class="k">باقی\u200cمانده</span><span class="v">{{ remaining_str }}</span></div>\n    {% if pct > 0 %}<div class="bar"><i style="width:{{ pct }}%"></i></div>{% endif %}\n    <div class="row"><span class="k">تاریخ انقضا</span><span class="v">{{ expire_str }}</span></div>\n    <div class="row"><span class="k">اتصالات فعال</span><span class="v">{{ active }}{% if user.max_conn > 0 %} / {{ user.max_conn }}{% endif %}</span></div>\n    <div class="row"><span class="k">پروتکل</span><span class="v">{{ user.protocol|upper }}</span></div>\n  </div>\n  <div class="card">\n    <h3><svg viewBox="0 0 24 24"><path d="M3.9 12c0-1.7 1.4-3.1 3.1-3.1h4V7H7c-2.8 0-5 2.2-5 5s2.2 5 5 5h4v-1.9H7c-1.7 0-3.1-1.4-3.1-3.1zM8 13h8v-2H8v2zm9-6h-4v1.9h4c1.7 0 3.1 1.4 3.1 3.1s-1.4 3.1-3.1 3.1h-4V17h4c2.8 0 5-2.2 5-5s-2.2-5-5-5z"/></svg> لینک\u200cها</h3>\n    <div class="btns">\n      <button class="btn btn-p" onclick="cp(\'{{ sub_url }}\')">کپی لینک سابسکریپشن</button>\n      {% if user.vless %}<button class="btn btn-o" onclick="cp(\'{{ user.vless }}\')">کپی کانفیگ VLESS</button>{% endif %}\n      {% if user.trojan %}<button class="btn btn-o" onclick="cp(\'{{ user.trojan }}\')">کپی کانفیگ Trojan</button>{% endif %}\n    </div>\n    <div class="linkbox">{{ sub_url }}</div>\n    {% if user.vless %}\n    <div class="qr"><img src="/qr/{{ user.uuid }}?proto=vless" alt="QR"><p style="font-size:.78rem;color:var(--muted);margin-top:.4rem">اسکن برای افزودن سریع</p></div>\n    {% endif %}\n  </div>\n  <p class="foot">Prism Panel · {{ domain }}</p>\n</div>\n<script>function cp(t){navigator.clipboard.writeText(t).then(()=>alert(\'کپی شد!\'))}</script>\n</body>\n</html>'
